class Solution:
    def expandRepeats(self, s: str) -> str:
        stack = []
        cur, k = [], 0
        for ch in s:
            if ch.isdigit():
                k = k * 10 + int(ch)
            elif ch == "[":
                stack.append((cur, k))
                cur, k = [], 0
            elif ch == "]":
                prefix, count = stack.pop()
                prefix.append("".join(cur) * count)
                cur = prefix
            else:
                cur.append(ch)
        return "".join(cur)

