  let i = 0;
  const parse = (): string => {
    let out = "";
    while (i < s.length && s[i] !== "]") {
      if (s[i] >= "0" && s[i] <= "9") {
        let k = 0;
        while (s[i] !== "[") k = k * 10 + (s.charCodeAt(i++) - 48);
        i++; // skip '['
        const inner = parse();
        i++; // skip ']'
        out += inner.repeat(k);
      } else out += s[i++];
    }
    return out;
  };
  return parse();
}

